class User {
  constructor(name) { this.name = name; }
  describe() { return `${this.name} (user)`; }
}
class Admin extends User {
  canDelete() { return true; }
}

const a = new Admin('Riya');
console.log(a.describe());                                  // Riya (user)
console.log(Object.getPrototypeOf(a) === Admin.prototype);  // true
console.log(Object.hasOwn(a, 'describe'));                  // false: inherited

const detached = a.describe;
try { detached(); } catch (e) { console.log(e.constructor.name); } // TypeError
const bound = a.describe.bind(a);
console.log(bound());                                       // Riya (user)

'use strict';
function who() { return this ? this.label : 'undefined'; }
const x = { label: 'x', who };
const y = { label: 'y' };

console.log(who());            // default binding
console.log(x.who());          // implicit binding
console.log(who.call(y));      // explicit binding
const Ctor = function () { this.label = 'new'; this.r = who.call(this); };
console.log(new Ctor().r);     // new binding

